Let E2TC be run on a stochastic contextual bandit with pre-training. Let Assumptions~\ref{as:context},~\ref{as:realizability}, and~\ref{as:bound} hold. Assume also that the weights $(\overline{\w},\overline{\theta})$ after the two exploration phases satisfy the following bound with $\PP\ge 1-\delta$:
\begin{equation}
  \risk(\overline{\w},\overline{\theta})-\risk(\wstar,\theta^*) <\epsilon(T_1,T_2,\delta).\label{eq:abstract_highp_risk}
\end{equation}
Then the regret of E2TC will be bounded by
\begin{equation}
  \E\left[ R_{1:T} \right] \le 2B_\w B_\phi T\delta + 2B_\w B_\phi(T_1+T_2)+K(T-T_1-T_2)\sqrt{\epsilon(T_1,T_2,\delta)}. \label{eq:abstract_regret}
\end{equation}

Let E2TC be run with ${T_2=0}$ (only the first stage of exploration). Let Assumptions~\ref{as:context},~\ref{as:realizability},~\ref{as:bound} hold. There exist $N_0\in\mathbb{N}$ and a universal constant $C>0$ such that, whenever $T_1>N_0$, with $\lambda=T_1^{-1 /2}$, the following statements hold simultaneously:
  \begin{enumerate}
    \item With $\PP\ge 1-C / \sqrt{T_1}$,
      \begin{equation}
        \norm{\wzero-\wstar}_{\sigz}^2=O\left(\epsilon_0^2d+ \frac{1}{\sqrt{T_1} } \right). \label{eq:wclose_sigz_datapoor}
      \end{equation}
    \item Regret of E2TC the following asymptotics:
    \begin{equation}
      R_{1:T}=O\left(TT_1^{-1 /2}+T_1 +\epsilon_0 \sqrt{\min\{\dht,\defft\}} KT+T_1^{-1 /4}KT\right).

Let E2TC be run with $T_2=0$ (only the first stage of exploration). Let Assumptions~\ref{as:context},~\ref{as:realizability},~\ref{as:bound} hold. Let $a>0$. There exist $N_0(a)\in\N$ such that, whenever $T_1>\max\{N_0, d^{1 /a}\}$, with
\begin{equation}
  \lambda:=\frac{7 B_\phi^2 \log T_1}{T_1}, \label{eq:lambdatwo}
\end{equation}
the following statements hold simultaneously:
\begin{enumerate}
  \item With $\PP>1-4 /\sqrt{T_1} $,
    \begin{equation}
      \norm{\w_0-\wstar}_{\sigz}^2=\widetilde{O}\left( \epsilon_0^2d+\frac{d}{T_1} \right).
    \end{equation}
  \item Regret of E2TC has the following asymptotics:

Assume that $\risk$ is convex, $\norm{\mathbf{v}_t}\le D $ a.s., and the domain $\dom$ is a $B_\omega$-ball:
\begin{equation}
  \dom=\left\{ \omega:\ \norm{\omega}\le B_\omega \right\}.
\end{equation}
Then, for any $\delta>0$, with probability not less than $1-\delta$,
\begin{equation}
  \risk(\overline{\omega})-\risk(\omega^*)< \frac{\norm{\omega^*-\omega_1}^2}{2\zeta T}+\frac{\zeta}{2T}\sum_{t=1}^{T} \norm{\gv_t}^2+
  4 D  B_\omega \sqrt{\frac{2}{T}\log \frac{1}{\delta}}. \label{eq:subopt_bound_sgd_default}
\end{equation}

Then, with probability $\PP\ge 1-2\delta$, the entire trajectory of SGD will be contained within $\mathcal{C}$ ($\forall t\ \omega_t\in\mathcal{C}$) and the suboptimality gap will be bounded as
  \begin{equation}
    \risk(\overline{\omega})-\risk(\omega^*)< \frac{\epsilon^2}{2\zeta T}+\frac{\zeta  D ^2}{2}+4 D  B_\omega \sqrt{\frac{2}{T}\log \frac{1}{\delta}}. \label{eq:contained_sgd_suboptimality_bound}
  \end{equation}

Then the constraints~\eqref{eq:require_small_epsilons} and~\eqref{eq:require_small_zeta} are met and E2TC satisfies
  \begin{align}
        \risk(\overline{\w},\overline{\theta})-\risk(\wstar,\theta^*)=
  O\Bigg(& \sqrt{\frac{\log(1 /\delta)}{T_2}} \left(1+\frac{\epsilon_0^2d+\epsilon_\theta^2}{\Delta\epsilon}+\frac{\Delta\epsilon}{\log(1 / \delta)}\right) \notag\\
  & +\frac{\Delta\epsilon^2 d^{1-\alpha /2}}{(1+\epsilon_0^2d)\log(d /\delta)\sqrt{T_2} T_{\mathrm{exp}}^{\beta /2}}  \Bigg)\label{eq:suboptimality_nocov}
  \end{align}
with probability not less than $1-10\delta$.

Then, the regret of E2TC admits a bound
\begin{equation}
  R_{1:T}=\widetilde{O}(T_1+T_2+KT T_2^{-1 /4} + KT\sqrt{d}T_1^{-1 /4} T_2^{-1 /4}). \label{eq:e2tc_regret}
\end{equation}
